// SSHService lets a plugin open SSH connections to hosts it names itself and
// run commands there — typically to bootstrap the GameAP daemon on a machine
// it has just provisioned, which is the one job gameap-nodecmd cannot do
// because no daemon exists yet.
//
// This is a deliberate exception to the gameap-net rule that the host picks
// the target. It is therefore gated twice: on the plugin's own "ssh"
// permission and on the operator's PLUGIN_SSH_ENABLED switch. Targets go
// through the same address policy as gameap-http, and cloud-metadata
// addresses are never reachable.
//
// Connection handles and operations live in the memory of the panel instance
// that created them: they are not shared between instances and do not survive
// a plugin reload.
// go:plugin type=host module=gameap-ssh
type SSHService interface {
	// GenerateKeyPair creates a key pair the plugin installs on the target
	// (through a provider API or cloud-init) and later passes to Connect. The
	// private key is returned once and the panel does not keep it.
	GenerateKeyPair(context.Context, *GenerateKeyPairRequest) (*GenerateKeyPairResponse, error)
	// Connect dials, verifies the host key against the requested policy,
	// authenticates and returns a connection handle. Blocking; the budget is
	// capped by the panel and by the guest call deadline.
	Connect(context.Context, *ConnectRequest) (*ConnectResponse, error)
	// Disconnect closes a handle; operations still running on it finish as
	// EXEC_STATUS_CANCELED.
	Disconnect(context.Context, *DisconnectRequest) (*DisconnectResponse, error)
	// Exec runs a command and blocks until it finishes or the wait budget
	// (timeout_seconds, additionally capped by the guest call deadline) runs
	// out. A timed-out wait answers completed=false with the operation id: the
	// command keeps running, poll GetExecOperation. Completion callbacks are
	// delivered only for a blocking call that returned completed=false, so a
	// short command does not push a redundant event into the plugin.
	Exec(context.Context, *ExecRequest) (*ExecSyncResponse, error)
	// StartExec returns an operation id immediately; completion is delivered
	// through the optional SSHExecEventsHandler service and observable via
	// GetExecOperation.
	StartExec(context.Context, *ExecRequest) (*StartExecResponse, error)
	// GetExecOperation reports an operation started by this plugin on this
	// panel instance; finished entries expire minutes after completion. With
	// wait_ms > 0 the call waits for the operation to finish, bounded by the
	// guest call deadline.
	GetExecOperation(context.Context, *GetExecOperationRequest) (*GetExecOperationResponse, error)
	// CancelExec is fire-and-forget: the operation finishes as
	// EXEC_STATUS_CANCELED once the remote command is torn down.
	CancelExec(context.Context, *CancelExecRequest) (*CancelExecResponse, error)
	// WriteFile and ReadFile stream through a remote `cat`, so the target needs
	// no SFTP subsystem. Both are bounded by the same output and stdin caps as
	// Exec.
	WriteFile(context.Context, *WriteFileRequest) (*WriteFileResponse, error)
	ReadFile(context.Context, *ReadFileRequest) (*ReadFileResponse, error)
}

// SSHExecEventsHandler is implemented by plugins that want the result of a
// long-running command pushed instead of polled. The panel calls it once per
// operation; the plugin then fetches the output with GetExecOperation.
//
// The callback runs on the panel instance that owns the operation. Plugin
// state is per-instance, so a handler that must survive a restart should
// persist what it learns (gameap-storage) rather than keep it in memory.
// go:plugin type=plugin version=1
type SSHExecEventsHandler interface {
	HandleExecCompleted(context.Context, *HandleExecCompletedRequest) (*HandleExecCompletedResponse, error)
}
